#!/usr/bin/env python3
# PROJEINDIR BOT - TAM GUNCELLEME (v91 -> v102), tek dosya.
# Hangi surumde olursan ol: eksik olanlari uygular, var olanlari atlar. Iki kez calistirmak zararsizdir.
# Kullanim:  python tam_guncelleme.py .
import sys, io, os, base64, contextlib
KOK = sys.argv[1] if len(sys.argv) > 1 else "."
if not os.path.exists(os.path.join(KOK, "app/src/main/java/com/kanka/makro/MacroService.kt")):
    print("! MakroApp klasorunde degilsin (MacroService.kt bulunamadi). Once: cd ~/MakroApp"); sys.exit(1)
PARCALAR = [('v91: imza guvenligi + yedek ekran okuma + durum bandi + seri kaldirildi', ''), ('v92: otomatik oyun tanima', ''), ('v93: panel baslat hizi + surukleme + upgrade admin', ''), ('v94: ozel oyun ekleme', ''), ('v96-97: ozel oyun duzeltme + listede secim + isi durdurma kapali', ''), ('v98: ozel oyun ekran tanima + cizerek egitim', ''), ('v99: POT TURU + ozel oyun yollari ayri', ''), ('v100: GLOBAL oyun-uygulama eslesmesi (MykoMobile/MykoOnline karismasi bitti)', ''), ("v101: EKRAN TANIMAZSA EGIT (her oyunda 'ekrani ogret' adimi)", ''), ('v102: ADIM ADIM EKRAN OGRETME (can/mana -> mob -> Open -> Collect All)', '')]
toplam_hata = 0
for ad, b64 in PARCALAR:
    kod = base64.b64decode(b64).decode("utf-8")
    buf = io.StringIO()
    eski = sys.argv; sys.argv = ["parca", KOK]
    with contextlib.redirect_stdout(buf):
        try:
            exec(compile(kod, ad, "exec"), {"__name__": "__main__"})
        except SystemExit:
            pass
        except Exception as e:
            print("! PARCA HATASI:", repr(e))
    sys.argv = eski
    cikti = buf.getvalue()
    hatalar = [l for l in cikti.splitlines() if l.strip().startswith("!") or "DOSYAYA YAZILMADI" in l]
    yeni = sum(1 for l in cikti.splitlines() if l.strip().startswith("+"))
    durum = "HATA" if hatalar else ("uygulandi (" + str(yeni) + " degisiklik)" if yeni else "zaten guncel")
    print(("X " if hatalar else "OK ") + ad + "  ->  " + durum)
    for l in hatalar: print("     " + l.strip())
    toplam_hata += len(hatalar)
print()
if toplam_hata:
    print("SONUC: %d HATA var. Push ETME, bu ciktinin ekran goruntusunu gonder." % toplam_hata); sys.exit(1)
print("SONUC: HATA YOK - simdi commit + push yapabilirsin.")
